-- Joy's starter slips (its seed migrations 0002-0023, as of Nov 2026). A new couple's jar is
-- filled from here; text placeholders {a}, {b}, {a_area}, {b_area} and [[...]] are filled when shown.

CREATE TABLE joy_seed_activities (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', est_cost INTEGER NOT NULL DEFAULT 0, setting TEXT NOT NULL,
    area TEXT NOT NULL DEFAULT '', venue TEXT NOT NULL DEFAULT '', lat REAL, lng REAL, duration TEXT NOT NULL,
    tags TEXT NOT NULL DEFAULT '', energy TEXT NOT NULL DEFAULT 'med', added_by TEXT NOT NULL DEFAULT '',
    generated INTEGER NOT NULL DEFAULT 0, closed_days TEXT NOT NULL DEFAULT '', season_from INTEGER, season_to INTEGER,
    hours TEXT NOT NULL DEFAULT '', best_time TEXT NOT NULL DEFAULT '', minutes INTEGER, booking TEXT NOT NULL DEFAULT '',
    book_ahead_days INTEGER, cover TEXT NOT NULL DEFAULT '', bring TEXT NOT NULL DEFAULT '', station TEXT NOT NULL DEFAULT '',
    station_walk_min INTEGER
);

